// bmRequest is one request that the fake bare metal API received
type bmRequest struct {
	method string
	path   string
	query  url.Values
	body   []byte
	header http.Header
}

func (r bmRequest) String() string { return r.method + " " + r.path + "?" + r.query.Encode() }

// fakeBaremetalAPI records every request and answers each bare metal route with a small valid body. The
// server list holds serverCount servers, and it pages them with the limit and offset of the request
type fakeBaremetalAPI struct {
	server      *httptest.Server
	serverCount int
	mu          sync.Mutex
	requests    []bmRequest
}

func newFakeBaremetalAPI(t *testing.T) *fakeBaremetalAPI {
	t.Helper()
	api := &fakeBaremetalAPI{serverCount: 1}
	api.server = httptest.NewServer(http.HandlerFunc(api.handle))
	t.Cleanup(api.server.Close)
	return api
}

// client returns a client with the project 7 and the region 99. Global routes must not use the region
func (a *fakeBaremetalAPI) client(opts ...option.RequestOption) *gcore.Client {
	client := gcore.NewClient(append([]option.RequestOption{
		option.WithBaseURL(a.server.URL),
		option.WithAPIKey("test"),
		option.WithCloudProjectID(7),
		option.WithCloudRegionID(99),
		option.WithMaxRetries(0),
	}, opts...)...)
	return &client
}

func (a *fakeBaremetalAPI) all() []bmRequest {
	a.mu.Lock()
	defer a.mu.Unlock()
	return slices.Clone(a.requests)
}

// only returns the one request that the API received
func (a *fakeBaremetalAPI) only(t *testing.T) bmRequest {
	t.Helper()
	requests := a.all()
	if len(requests) != 1 {
		t.Fatalf("requests = %v, want exactly one", requests)
	}
	return requests[0]
}

func (a *fakeBaremetalAPI) handle(w http.ResponseWriter, r *http.Request) {
	body, _ := io.ReadAll(r.Body)
	a.mu.Lock()
	a.requests = append(a.requests, bmRequest{method: r.Method, path: r.URL.Path, query: r.URL.Query(), body: body, header: r.Header.Clone()})
	a.mu.Unlock()

	// a dry run returns the schema of the real call with an empty task list
	tasks := []string{"task-1"}
	if r.URL.Query().Get("dry_run") == "true" {
		tasks = []string{}
	}
	var res any
	switch {
	case strings.HasPrefix(r.URL.Path, "/cloud/v1/tasks/"):
		res = map[string]any{
			"id":                strings.TrimPrefix(r.URL.Path, "/cloud/v1/tasks/"),
			"state":             cloud.TaskStateFinished,
			"task_type":         "create_bm",
			"created_on":        "2026-11-19T10:00:00",
			"created_resources": map[string]any{"instances": []string{bmServerID}, "baremetal_server": []string{}},
		}
	case r.Method == http.MethodGet && strings.HasSuffix(r.URL.Path, "/baremetal/flavors"):
		res = map[string]any{"count": 1, "results": []any{bmFlavorJSON}}
	case r.Method == http.MethodGet && strings.HasSuffix(r.URL.Path, "/baremetal/servers"):
		res = a.serverPage(r.URL.Query())
	case r.Method == http.MethodGet && strings.HasSuffix(r.URL.Path, "/console"):
		res = map[string]any{"remote_console": map[string]any{"protocol": "vnc", "type": "novnc", "url": "https://console.example.com/bm-1"}}
	case r.Method == http.MethodGet:
		res = bmServerJSON
	case r.Method == http.MethodDelete:
		res = map[string]any{
			"tasks":                 tasks,
			"resources_to_delete":   []map[string]any{{"id": bmServerID, "name": "bm-1", "type": "baremetal_servers"}},
			"resources_to_preserve": []map[string]any{{"id": bmPort1ID, "name": nil, "type": "ports"}},
		}
	default:
		res = map[string]any{"tasks": tasks}
	}
	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(res)
}

func (a *fakeBaremetalAPI) serverPage(query url.Values) map[string]any {
	offset, _ := strconv.Atoi(query.Get("offset"))
	limit, err := strconv.Atoi(query.Get("limit"))
	if err != nil {
		limit = 10
	}
	results := []map[string]any{}
	for i := offset; i < a.serverCount && i < offset+limit; i++ {
		results = append(results, map[string]any{"id": fmt.Sprintf("00000000-0000-4000-8000-%012d", i+1), "name": fmt.Sprintf("db-%d", i+1)})
	}
	return map[string]any{"count": a.serverCount, "results": results}
}

// wantJSON checks that got is the same JSON value as want
func wantJSON(t *testing.T, got []byte, want string) {
	t.Helper()
	var gotValue, wantValue any
	if err := json.Unmarshal(got, &gotValue); err != nil {
		t.Fatalf("body %q is not JSON: %v", got, err)
	}
	if err := json.Unmarshal([]byte(want), &wantValue); err != nil {
		t.Fatalf("want %q is not JSON: %v", want, err)
	}
	if !reflect.DeepEqual(gotValue, wantValue) {
		t.Errorf("body = %s, want %s", got, want)
	}
}

// wantQuery checks the query parameters of a request
func wantQuery(t *testing.T, got url.Values, want url.Values) {
	t.Helper()
	if !reflect.DeepEqual(got, want) {
		t.Errorf("query = %q, want %q", got.Encode(), want.Encode())
	}
}

// TestBaremetalServerRoutes checks the method and the path of each global operation. The paths have no
// region, although the client has a default region
func TestBaremetalServerRoutes(t *testing.T) {
	ctx := context.Background()
	serverPath := bmProjectPath + "/servers/" + bmServerID
	cases := []struct {
		name   string
		method string
		path   string
		call   func(client *gcore.Client) error
	}{
		{"New", http.MethodPost, bmProjectPath + "/servers", func(client *gcore.Client) error {
			_, err := client.Cloud.Baremetal.Servers.New(ctx, cloud.BaremetalServerNewParams{
				RegionID:   5,
				FlavorName: "bm2-hf-small",
				ImageID:    bmImageID,
				Interfaces: []cloud.BaremetalServerNewParamsInterface{{PortID: bmPort1ID}},
			})
			return err
		}},
		{"List", http.MethodGet, bmProjectPath + "/servers", func(client *gcore.Client) error {
			_, err := client.Cloud.Baremetal.Servers.List(ctx, cloud.BaremetalServerListParams{})
			return err
		}},
		{"Get", http.MethodGet, serverPath, func(client *gcore.Client) error {
			_, err := client.Cloud.Baremetal.Servers.Get(ctx, bmServerID, cloud.BaremetalServerGetParams{})
			return err
		}},
		{"Update", http.MethodPatch, serverPath, func(client *gcore.Client) error {
			_, err := client.Cloud.Baremetal.Servers.Update(ctx, bmServerID, cloud.BaremetalServerUpdateParams{Name: gcore.String("bm-2")})
			return err
		}},
		{"Delete", http.MethodDelete, serverPath, func(client *gcore.Client) error {
			_, err := client.Cloud.Baremetal.Servers.Delete(ctx, bmServerID, cloud.BaremetalServerDeleteParams{})
			return err
		}},
		{"Action", http.MethodPost, serverPath + "/action", func(client *gcore.Client) error {
			_, err := client.Cloud.Baremetal.Servers.Action(ctx, bmServerID, cloud.BaremetalServerActionParams{
				Action: cloud.BaremetalServerActionParamsActionReboot,
			})
			return err
		}},
		{"Console.Get", http.MethodGet, serverPath + "/console", func(client *gcore.Client) error {
			_, err := client.Cloud.Baremetal.Servers.Console.Get(ctx, bmServerID, cloud.BaremetalServerConsoleGetParams{})
			return err
		}},
		{"Flavors.List", http.MethodGet, bmProjectPath + "/flavors", func(client *gcore.Client) error {
			_, err := client.Cloud.Baremetal.Flavors.List(ctx, cloud.BaremetalFlavorListParams{})
			return err
		}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			api := newFakeBaremetalAPI(t)
			if err := tc.call(api.client()); err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			// the raw methods send one request and do not poll
			request := api.only(t)
			if request.method != tc.method || request.path != tc.path {
				t.Errorf("request = %s %s, want %s %s", request.method, request.path, tc.method, tc.path)
			}
			// the default region of the client is not a filter of the lists
			if request.query.Has("region_ids") || request.query.Has("region_id") {
				t.Errorf("query = %q, want no region", request.query.Encode())
			}
		})
	}
}

// TestBaremetalServerNewRequest checks the create body: the region of the params, the image, the flavor and
// the ports in their order. An omitted port_group stays out of the body, because DPU hardware rejects it
func TestBaremetalServerNewRequest(t *testing.T) {
	api := newFakeBaremetalAPI(t)
	client := api.client()

	res, err := client.Cloud.Baremetal.Servers.New(context.Background(), cloud.BaremetalServerNewParams{
		RegionID:   5,
		FlavorName: "bm2-hf-small",
		ImageID:    bmImageID,
		Interfaces: []cloud.BaremetalServerNewParamsInterface{
			{PortID: bmPort1ID},
			{PortID: bmPort2ID, PortGroup: gcore.Int(1)},
		},
		Name:     gcore.String("bm-1"),
		SSHKeyID: gcore.String(bmSSHKeyID),
		Tags:     map[string]string{"env": "prod"},
	})
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if !slices.Equal(res.Tasks, []string{"task-1"}) {
		t.Errorf("Tasks = %q, want the task IDs of the response", res.Tasks)
	}
	request := api.only(t)
	wantQuery(t, request.query, url.Values{})
	// the region comes from the params, not from the client region 99
	wantJSON(t, request.body, fmt.Sprintf(`{
		"region_id": 5,
		"flavor_name": "bm2-hf-small",
		"image_id": %q,
		"interfaces": [{"port_id": %q}, {"port_id": %q, "port_group": 1}],
		"name": "bm-1",
		"ssh_key_id": %q,
		"tags": {"env": "prod"}
	}`, bmImageID, bmPort1ID, bmPort2ID, bmSSHKeyID))
}

// TestBaremetalServerListPages checks that the auto pager reads every page. Each request keeps the filters,
// and the next page has a larger offset. Object filters use brackets, not dots
func TestBaremetalServerListPages(t *testing.T) {
	api := newFakeBaremetalAPI(t)
	api.serverCount = 3
	client := api.client()

	iter := client.Cloud.Baremetal.Servers.ListAutoPaging(context.Background(), cloud.BaremetalServerListParams{
		Limit:    gcore.Int(2),
		Name:     cloud.BaremetalServerListParamsName{Contains: []string{"db"}},
		Tags:     map[string][]string{"env": {"prod"}},
		Statuses: []string{"active", "stopped"},
	})
	var names []string
	for iter.Next() {
		names = append(names, iter.Current().Name)
	}
	if err := iter.Err(); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if want := []string{"db-1", "db-2", "db-3"}; !slices.Equal(names, want) {
		t.Errorf("names = %q, want %q", names, want)
	}

	requests := api.all()
	if len(requests) != 2 {
		t.Fatalf("requests = %v, want two pages", requests)
	}
	filters := url.Values{
		"limit":          {"2"},
		"name[contains]": {"db"},
		"tags[env]":      {"prod"},
		"statuses":       {"active", "stopped"},
	}
	for i, offset := range []string{"", "2"} {
		want := url.Values{}
		for key, values := range filters {
			want[key] = values
		}
		if offset != "" {
			want.Set("offset", offset)
		}
		if requests[i].path != bmProjectPath+"/servers" {
			t.Errorf("page %d path = %s, want %s", i+1, requests[i].path, bmProjectPath+"/servers")
		}
		wantQuery(t, requests[i].query, want)
	}
}

// TestBaremetalFlavorListRequest checks the flavor filters and the flavor model. Range and name filters
// use brackets
func TestBaremetalFlavorListRequest(t *testing.T) {
	api := newFakeBaremetalAPI(t)
	client := api.client()

	page, err := client.Cloud.Baremetal.Flavors.List(context.Background(), cloud.BaremetalFlavorListParams{
		RegionIDs:             []int64{5},
		CompatibleWithImageID: gcore.String(bmImageID),
		Name:                  cloud.BaremetalFlavorListParamsName{Prefix: []string{"bm2-"}},
		CPUThreads:            cloud.BaremetalFlavorListParamsCPUThreads{Gte: gcore.Int(8)},
		RamMib:                cloud.BaremetalFlavorListParamsRamMib{Lte: gcore.Int(131072)},
		OsTypes:               []string{"linux"},
		OrderBy:               cloud.BaremetalFlavorListParamsOrderByRamMibAsc,
	})
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	wantQuery(t, api.only(t).query, url.Values{
		"region_ids":               {"5"},
		"compatible_with_image_id": {bmImageID},
		"name[prefix]":             {"bm2-"},
		"cpu_threads[gte]":         {"8"},
		"ram_mib[lte]":             {"131072"},
		"os_types":                 {"linux"},
		"order_by":                 {"ram_mib.asc"},
	})

	if len(page.Results) != 1 {
		t.Fatalf("results = %d, want 1", len(page.Results))
	}
	flavor := page.Results[0]
	if flavor.Name != "bm2-hf-small" || flavor.RegionID != 5 || flavor.CPUThreads != 16 || flavor.RamMib != 65536 {
		t.Errorf("flavor = %+v, want the name, region, CPU threads and RAM of the response", flavor)
	}
	if flavor.Capacity != 3 || flavor.ReservedCapacity != 1 {
		t.Errorf("capacity = %d, reserved = %d, want 3 and 1", flavor.Capacity, flavor.ReservedCapacity)
	}
	if caps := flavor.NetworkingCapabilities; !caps.SecurityGroups || caps.PortSecurity || caps.AllowedAddressPairs {
		t.Errorf("networking capabilities = %+v, want only security groups", caps)
	}
}

// TestBaremetalServerUpdateRequest checks that the update body has only the fields that the caller sets. A
// null tag value stays null, and the interfaces keep their order
func TestBaremetalServerUpdateRequest(t *testing.T) {
	cases := []struct {
		name   string
		params cloud.BaremetalServerUpdateParams
		want   string
	}{
		{
			name:   "name only",
			params: cloud.BaremetalServerUpdateParams{Name: gcore.String("bm-2")},
			want:   `{"name": "bm-2"}`,
		},
		{
			name:   "remove a tag",
			params: cloud.BaremetalServerUpdateParams{Tags: cloud.TagUpdateMap{"old": nil, "env": gcore.Ptr("prod")}},
			want:   `{"tags": {"old": null, "env": "prod"}}`,
		},
		{
			// the full list with the new port at the end, in one request, with no attach call
			name: "append an interface",
			params: cloud.BaremetalServerUpdateParams{Interfaces: []cloud.BaremetalServerUpdateParamsInterface{
				{PortID: bmPort1ID},
				{PortID: bmPort2ID},
				{PortID: bmPort3ID, PortGroup: gcore.Int(1)},
			}},
			want: fmt.Sprintf(`{"interfaces": [{"port_id": %q}, {"port_id": %q}, {"port_id": %q, "port_group": 1}]}`, bmPort1ID, bmPort2ID, bmPort3ID),
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			api := newFakeBaremetalAPI(t)
			res, err := api.client().Cloud.Baremetal.Servers.Update(context.Background(), bmServerID, tc.params)
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if !slices.Equal(res.Tasks, []string{"task-1"}) {
				t.Errorf("Tasks = %q, want the task IDs of the response", res.Tasks)
			}
			request := api.only(t)
			if request.method != http.MethodPatch {
				t.Errorf("method = %s, want PATCH", request.method)
			}
			wantJSON(t, request.body, tc.want)
		})
	}
}

// TestBaremetalServerDeleteRequest checks the resource options of the delete. By default the delete sends no
// option, so the ports and floating IPs stay
func TestBaremetalServerDeleteRequest(t *testing.T) {
	cases := []struct {
		name   string
		params cloud.BaremetalServerDeleteParams
		want   url.Values
	}{
		{
			name: "default keeps the ports and floating IPs",
			want: url.Values{},
		},
		{
			name:   "selected ports and floating IPs",
			params: cloud.BaremetalServerDeleteParams{PortIDs: []string{bmPort1ID, bmPort2ID}, FloatingIPIDs: []string{bmFloatingID}},
			want:   url.Values{"port_ids": {bmPort1ID, bmPort2ID}, "floating_ip_ids": {bmFloatingID}},
		},
		{
			name:   "all ports and floating IPs",
			params: cloud.BaremetalServerDeleteParams{AllPorts: gcore.Bool(true), AllFloatingIPs: gcore.Bool(true)},
			want:   url.Values{"all_ports": {"true"}, "all_floating_ips": {"true"}},
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			api := newFakeBaremetalAPI(t)
			res, err := api.client().Cloud.Baremetal.Servers.Delete(context.Background(), bmServerID, tc.params)
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			request := api.only(t)
			wantQuery(t, request.query, tc.want)
			if len(request.body) != 0 {
				t.Errorf("body = %s, want none", request.body)
			}
			if len(res.ResourcesToDelete) != 1 || res.ResourcesToDelete[0].ID != bmServerID {
				t.Errorf("ResourcesToDelete = %+v, want the server", res.ResourcesToDelete)
			}
			if len(res.ResourcesToPreserve) != 1 || res.ResourcesToPreserve[0].Type != "ports" {
				t.Errorf("ResourcesToPreserve = %+v, want the port", res.ResourcesToPreserve)
			}
		})
	}
}

// TestBaremetalServerActionAndConsoleRequest checks the action body and the console query. Without a
// console type, the request sends none and the hardware picks it
func TestBaremetalServerActionAndConsoleRequest(t *testing.T) {
	ctx := context.Background()
	t.Run("hard reboot", func(t *testing.T) {
		api := newFakeBaremetalAPI(t)
		res, err := api.client().Cloud.Baremetal.Servers.Action(ctx, bmServerID, cloud.BaremetalServerActionParams{
			Action: cloud.BaremetalServerActionParamsActionRebootHard,
		})
		if err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		if !slices.Equal(res.Tasks, []string{"task-1"}) {
			t.Errorf("Tasks = %q, want the task IDs of the response", res.Tasks)
		}
		wantJSON(t, api.only(t).body, `{"action": "reboot_hard"}`)
	})
	t.Run("console without a type", func(t *testing.T) {
		api := newFakeBaremetalAPI(t)
		console, err := api.client().Cloud.Baremetal.Servers.Console.Get(ctx, bmServerID, cloud.BaremetalServerConsoleGetParams{})
		if err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		wantQuery(t, api.only(t).query, url.Values{})
		remote := console.RemoteConsole
		if remote.Protocol != "vnc" || remote.Type != "novnc" || remote.URL != "https://console.example.com/bm-1" {
			t.Errorf("console = %+v, want the protocol, type and URL of the response", remote)
		}
	})
	t.Run("console with a type", func(t *testing.T) {
		api := newFakeBaremetalAPI(t)
		_, err := api.client().Cloud.Baremetal.Servers.Console.Get(ctx, bmServerID, cloud.BaremetalServerConsoleGetParams{
			ConsoleType: cloud.BaremetalServerConsoleGetParamsConsoleTypeSerial,
		})
		if err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		wantQuery(t, api.only(t).query, url.Values{"console_type": {"serial"}})
	})
}

// TestBaremetalServerGetModel checks the interfaces of a server: the bond of a parent port and a sub-port, and
// a DPU port whose bond and trunk are null
func TestBaremetalServerGetModel(t *testing.T) {
	api := newFakeBaremetalAPI(t)
	server, err := api.client().Cloud.Baremetal.Servers.Get(context.Background(), bmServerID, cloud.BaremetalServerGetParams{})
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if server.FlavorName != "bm2-hf-small" || server.ImageID != bmImageID || server.RegionID != 5 || server.Status != cloud.BaremetalServerStatusActive {
		t.Errorf("server = %+v, want the fields of the response", server)
	}
	if server.JSON.SSHKeyID.Valid() || server.JSON.ManagedBy.Valid() {
		t.Errorf("SSHKeyID and ManagedBy must be null")
	}
	if len(server.Interfaces) != 3 {
		t.Fatalf("interfaces = %d, want 3", len(server.Interfaces))
	}

	parent, subPort, dpu := server.Interfaces[0], server.Interfaces[1], server.Interfaces[2]
	if parent.PortID != bmPort1ID || !parent.JSON.PortGroup.Valid() || parent.PortGroup != 0 {
		t.Errorf("parent = %+v, want port %s in group 0", parent, bmPort1ID)
	}
	if _, ok := parent.Trunk.AsAny().(cloud.BaremetalServerInterfaceTrunkParent); !ok {
		t.Errorf("parent trunk = %s, want the parent role", parent.Trunk.RawJSON())
	}
	if trunk, ok := subPort.Trunk.AsAny().(cloud.BaremetalServerInterfaceTrunkSubPort); !ok || trunk.ParentPortID != bmPort1ID {
		t.Errorf("sub-port trunk = %s, want the sub_port role with parent %s", subPort.Trunk.RawJSON(), bmPort1ID)
	}
	if dpu.PortID != bmPort3ID || dpu.JSON.PortGroup.Raw() != "null" || dpu.JSON.Trunk.Raw() != "null" {
		t.Errorf("DPU interface = %+v, want null port_group and trunk", dpu)
	}
}

// TestBaremetalServerRawDryRun checks that a raw dry run sends dry_run=true and returns the empty task list
// without polling
func TestBaremetalServerRawDryRun(t *testing.T) {
	ctx := context.Background()
	cases := []struct {
		name string
		call func(client *gcore.Client) ([]string, error)
	}{
		{"New", func(client *gcore.Client) ([]string, error) {
			res, err := client.Cloud.Baremetal.Servers.New(ctx, cloud.BaremetalServerNewParams{
				RegionID:   5,
				FlavorName: "bm2-hf-small",
				ImageID:    bmImageID,
				Interfaces: []cloud.BaremetalServerNewParamsInterface{{PortID: bmPort1ID}},
				DryRun:     gcore.Bool(true),
			})
			if err != nil {
				return nil, err
			}
			return res.Tasks, nil
		}},
		{"Update", func(client *gcore.Client) ([]string, error) {
			res, err := client.Cloud.Baremetal.Servers.Update(ctx, bmServerID, cloud.BaremetalServerUpdateParams{Name: gcore.String("bm-2"), DryRun: gcore.Bool(true)})
			if err != nil {
				return nil, err
			}
			return res.Tasks, nil
		}},
		{"Action", func(client *gcore.Client) ([]string, error) {
			res, err := client.Cloud.Baremetal.Servers.Action(ctx, bmServerID, cloud.BaremetalServerActionParams{
				Action: cloud.BaremetalServerActionParamsActionStop,
				DryRun: gcore.Bool(true),
			})
			if err != nil {
				return nil, err
			}
			return res.Tasks, nil
		}},
		{"Delete", func(client *gcore.Client) ([]string, error) {
			res, err := client.Cloud.Baremetal.Servers.Delete(ctx, bmServerID, cloud.BaremetalServerDeleteParams{AllPorts: gcore.Bool(true), DryRun: gcore.Bool(true)})
			if err != nil {
				return nil, err
			}
			if len(res.ResourcesToDelete) != 1 || len(res.ResourcesToPreserve) != 1 {
				return nil, fmt.Errorf("resource lists = %+v and %+v, want one item each", res.ResourcesToDelete, res.ResourcesToPreserve)
			}
			return res.Tasks, nil
		}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			api := newFakeBaremetalAPI(t)
			tasks, err := tc.call(api.client())
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if tasks == nil || len(tasks) != 0 {
				t.Errorf("Tasks = %#v, want an empty list", tasks)
			}
			if got := api.only(t).query.Get("dry_run"); got != "true" {
				t.Errorf("dry_run = %q, want true", got)
			}
		})
	}
}

// TestBaremetalServerAndPollRequestOptions checks that the helpers keep the request options of the caller.
// Each request has the custom header, the paths use the project of the client or of the call, and the
// response capture gets the server JSON, not the task JSON
func TestBaremetalServerAndPollRequestOptions(t *testing.T) {
	ctx := context.Background()
	type helperFunc func(client *gcore.Client, opts ...option.RequestOption) (*cloud.BaremetalServer, error)
	helpers := []struct {
		name     string
		mutation string
		invoke   helperFunc
	}{
		{"NewAndPoll", "POST /servers", func(client *gcore.Client, opts ...option.RequestOption) (*cloud.BaremetalServer, error) {
			return client.Cloud.Baremetal.Servers.NewAndPoll(ctx, cloud.BaremetalServerNewParams{
				RegionID:   5,
				FlavorName: "bm2-hf-small",
				ImageID:    bmImageID,
				Interfaces: []cloud.BaremetalServerNewParamsInterface{{PortID: bmPort1ID}},
			}, opts...)
		}},
		{"UpdateAndPoll", "PATCH /servers/" + bmServerID, func(client *gcore.Client, opts ...option.RequestOption) (*cloud.BaremetalServer, error) {
			return client.Cloud.Baremetal.Servers.UpdateAndPoll(ctx, bmServerID, cloud.BaremetalServerUpdateParams{Name: gcore.String("bm-2")}, opts...)
		}},
		{"ActionAndPoll", "POST /servers/" + bmServerID + "/action", func(client *gcore.Client, opts ...option.RequestOption) (*cloud.BaremetalServer, error) {
			return client.Cloud.Baremetal.Servers.ActionAndPoll(ctx, bmServerID, cloud.BaremetalServerActionParams{
				Action: cloud.BaremetalServerActionParamsActionStart,
			}, opts...)
		}},
		{"DeleteAndPoll", "DELETE /servers/" + bmServerID, func(client *gcore.Client, opts ...option.RequestOption) (*cloud.BaremetalServer, error) {
			return nil, client.Cloud.Baremetal.Servers.DeleteAndPoll(ctx, bmServerID, cloud.BaremetalServerDeleteParams{}, opts...)
		}},
	}
	projects := []struct {
		name    string
		project string
		opts    []option.RequestOption
	}{
		{name: "client project", project: "7"},
		{name: "call project", project: "8", opts: []option.RequestOption{option.WithCloudProjectID(8)}},
	}
	for _, helper := range helpers {
		for _, project := range projects {
			t.Run(helper.name+"/"+project.name, func(t *testing.T) {
				api := newFakeBaremetalAPI(t)
				var raw []byte
				opts := append([]option.RequestOption{
					option.WithHeader("X-Test-Header", "bare-metal"),
					option.WithResponseBodyInto(&raw),
				}, project.opts...)
				server, err := helper.invoke(api.client(), opts...)
				if err != nil {
					t.Fatalf("unexpected error: %v", err)
				}

				prefix := "/cloud/v1/projects/" + project.project + "/baremetal"
				want := []string{
					strings.Replace(helper.mutation, " ", " "+prefix, 1),
					"GET /cloud/v1/tasks/task-1",
				}
				if helper.name != "DeleteAndPoll" {
					want = append(want, "GET "+prefix+"/servers/"+bmServerID)
				}
				var got []string
				for _, request := range api.all() {
					got = append(got, request.method+" "+request.path)
					if value := request.header.Get("X-Test-Header"); value != "bare-metal" {
						t.Errorf("%s %s: X-Test-Header = %q, want bare-metal", request.method, request.path, value)
					}
					if request.method == http.MethodGet && len(request.body) != 0 {
						t.Errorf("%s %s: body = %s, want none", request.method, request.path, request.body)
					}
				}
				if !slices.Equal(got, want) {
					t.Errorf("requests = %q, want %q", got, want)
				}

				if helper.name == "DeleteAndPoll" {
					if raw != nil {
						t.Errorf("captured body = %s, want none for a delete", raw)
					}
					return
				}
				if server == nil || server.ID != bmServerID || server.FlavorName != "bm2-hf-small" {
					t.Fatalf("server = %+v, want the server of the GET", server)
				}
				var captured map[string]any
				if err := json.Unmarshal(raw, &captured); err != nil {
					t.Fatalf("captured body %q is not JSON: %v", raw, err)
				}
				if captured["id"] != bmServerID || captured["flavor_name"] != "bm2-hf-small" {
					t.Errorf("captured body = %s, want the server JSON", raw)
				}
				if _, ok := captured["tasks"]; ok {
					t.Errorf("captured body = %s, want the server JSON, not the task list", raw)
				}
			})
		}
	}
}
